CREATE TABLE IF NOT EXISTS asset_positions(asset_id INTEGER PRIMARY KEY REFERENCES erp_objects(id),data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS asset_movements(id INTEGER PRIMARY KEY,asset_id INTEGER NOT NULL REFERENCES erp_objects(id),source_id INTEGER NOT NULL REFERENCES erp_objects(id),entity_id INTEGER NOT NULL REFERENCES erp_entities(id),exercise INTEGER NOT NULL,date TEXT NOT NULL,sequence INTEGER NOT NULL,fact TEXT NOT NULL,description TEXT NOT NULL,before_snapshot TEXT NOT NULL,after_snapshot TEXT NOT NULL,metadata TEXT NOT NULL,group_id TEXT NOT NULL,reversal_of INTEGER UNIQUE REFERENCES asset_movements(id),actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(asset_id,date,sequence));
CREATE INDEX IF NOT EXISTS asset_movements_history ON asset_movements(asset_id,date,id);
CREATE INDEX IF NOT EXISTS asset_movements_reports ON asset_movements(entity_id,exercise,date,fact);
CREATE TABLE IF NOT EXISTS asset_accounting_entries(movement_id INTEGER NOT NULL REFERENCES asset_movements(id),ledger_id INTEGER NOT NULL UNIQUE REFERENCES erp_ledger(id),class_id INTEGER NOT NULL REFERENCES erp_objects(id),location TEXT NOT NULL,PRIMARY KEY(movement_id,ledger_id));
CREATE TABLE IF NOT EXISTS asset_batches(id INTEGER PRIMARY KEY,entity_id INTEGER NOT NULL REFERENCES erp_entities(id),exercise INTEGER NOT NULL,operation TEXT NOT NULL,parameters TEXT NOT NULL,selection TEXT NOT NULL,preview TEXT NOT NULL,sha256 TEXT NOT NULL,state TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_by INTEGER NOT NULL REFERENCES users(id),reviewed_by INTEGER REFERENCES users(id),created_at TEXT NOT NULL,executed_at TEXT);
CREATE TABLE IF NOT EXISTS asset_batch_results(batch_id INTEGER NOT NULL REFERENCES asset_batches(id),asset_id INTEGER NOT NULL REFERENCES erp_objects(id),result TEXT NOT NULL,PRIMARY KEY(batch_id,asset_id));
CREATE TABLE IF NOT EXISTS asset_alerts(asset_id INTEGER NOT NULL REFERENCES erp_objects(id),period TEXT NOT NULL,kind TEXT NOT NULL,recipient_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,PRIMARY KEY(asset_id,period,kind,recipient_id));
CREATE TRIGGER IF NOT EXISTS asset_movements_no_update BEFORE UPDATE ON asset_movements BEGIN SELECT RAISE(ABORT,'Evento patrimonial preservado'); END;
CREATE TRIGGER IF NOT EXISTS asset_movements_no_delete BEFORE DELETE ON asset_movements BEGIN SELECT RAISE(ABORT,'Evento patrimonial preservado'); END;
CREATE TRIGGER IF NOT EXISTS asset_entries_no_update BEFORE UPDATE ON asset_accounting_entries BEGIN SELECT RAISE(ABORT,'Partida patrimonial preservada'); END;
CREATE TRIGGER IF NOT EXISTS asset_entries_no_delete BEFORE DELETE ON asset_accounting_entries BEGIN SELECT RAISE(ABORT,'Partida patrimonial preservada'); END;
CREATE TRIGGER IF NOT EXISTS asset_batch_results_no_update BEFORE UPDATE ON asset_batch_results BEGIN SELECT RAISE(ABORT,'Resultado patrimonial preservado'); END;
CREATE TRIGGER IF NOT EXISTS asset_batch_results_no_delete BEFORE DELETE ON asset_batch_results BEGIN SELECT RAISE(ABORT,'Resultado patrimonial preservado'); END;
